const items = $input.all();
const now = new Date().toISOString();
const results = [];

for (const item of items) {
  const p = item.json;
  const fileName = p.id + '_' + p.name + '.json';
  const objectKey = 'raw/' + fileName;
  const content = JSON.stringify(p);

  const buffer = Buffer.from(content, 'utf-8');

  results.push({
    json: {
      pokemon_id: p.id,
      pokemon_name: p.name,
      file_name: fileName,
      object_key: objectKey,
      bucket_name: 'raw-pokemon',
      file_type: 'json',
      mime_type: 'application/json',
      file_size: buffer.length,
      created_at: now
    },
    binary: {
      data: {
        data: buffer.toString('base64'),
        mimeType: 'application/json',
        fileName: fileName
      }
    }
  });
}

return results;

const prepared = $('Prepare Files').all();
const results = [];

for (const item of prepared) {
  const p = item.json;

  const insertFile = `INSERT INTO pokemon_files (pokemon_id, bucket_name, object_key, file_name, file_type, file_size, mime_type, created_at) VALUES (${p.pokemon_id}, '${p.bucket_name}', '${p.object_key}', '${p.file_name}', '${p.file_type}', ${p.file_size}, '${p.mime_type}', '${p.created_at}');`;

  const insertLog = `INSERT INTO file_ingestion_log (file_name, bucket_name, object_key, source, status, file_size, mime_type, processed_at) VALUES ('${p.file_name}', '${p.bucket_name}', '${p.object_key}', 'pokeapi', 'success', ${p.file_size}, '${p.mime_type}', '${p.created_at}');`;

  results.push({ json: { query: insertFile } });
  results.push({ json: { query: insertLog } });
}

return results;
